//! Parity and regression tests for the shared LM backbones.
//!
//! Pinned fixtures reside in `testdata/lm/<case>/`, generated by
//! `tools/gen_lm_fixtures.py` against mlx-audio 0.5.7 commit
//! `e1b19b9054bf163f5d812221a54fcc346f1890e9` (mlx 0.32.3). Every case is a
//! seeded tiny backbone: the traces carry the Python prefill logits, three
//! cached decode-step logits, a cacheless pass, and the post-norm hidden
//! state.

use std::path::{Path, PathBuf};

use serde_json::Value;

use super::cache::make_prompt_cache;
use super::engine::Input;
use super::{
    bailing_moe, cohere2, falcon_h1, gpt2, llama, qwen2, qwen3, LayerCaches, PromptCache, Weights,
};
use crate::Result;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/lm")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn f32_rows(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("rows")
        .iter()
        .flat_map(|row| {
            row.as_array()
                .expect("row")
                .iter()
                .map(|v| v.as_f64().unwrap() as f32)
        })
        .collect()
}

fn max_abs_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    // f32::max silently drops NaN, which would turn a NaN output into a
    // passing 0.0 diff; propagate NaN into the result instead so the
    // tolerance assert fails.
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, |best, diff| {
            if diff.is_nan() || diff > best {
                diff
            } else {
                best
            }
        })
}

/// The largest tolerance any fixture needed when the gates were frozen;
/// individual cases assert against it, not against re-measured values.
const LOGITS_TOLERANCE: f32 = 2e-4;
const HIDDEN_TOLERANCE: f32 = 2e-4;
/// The falcon_h1 conv/ssm state gate (same absolute scale as the logits).
const STATE_TOLERANCE: f32 = 2e-4;

/// The fixture model union. Each flavor forwards through its own cache
/// shape; cohere2 alternates dense and rotating caches, falcon_h1 carries
/// the Mamba conv/ssm pairs, the rest use the plain appending cache.
enum FixtureModel {
    Dense(super::Backbone),
    Gpt2(super::Gpt2Model),
    Cohere2(super::Cohere2Model),
    Moe(super::BailingMoeModel),
    Falcon(falcon_h1::FalconH1Model),
}

enum FixtureCaches {
    Dense(LayerCaches),
    Mixed(Vec<PromptCache>),
    Falcon(Vec<falcon_h1::FalconLayerCache>),
}

impl FixtureModel {
    fn load(name: &str, weights: &Weights, config: &Value) -> Self {
        if name.starts_with("llama") {
            Self::Dense(llama::load(weights, config).expect("model loads"))
        } else if name.starts_with("qwen2") {
            Self::Dense(qwen2::load(weights, config).expect("model loads"))
        } else if name.starts_with("qwen3") {
            Self::Dense(qwen3::load(weights, config).expect("model loads"))
        } else if name.starts_with("gpt2_indextts") {
            // The indextts patch: the position table is bypassed and the
            // input arrives as precomputed embeddings.
            Self::Gpt2(
                gpt2::load(weights, config)
                    .expect("model loads")
                    .without_position_embeddings(),
            )
        } else if name.starts_with("gpt2") {
            Self::Gpt2(gpt2::load(weights, config).expect("model loads"))
        } else if name.starts_with("cohere2") {
            Self::Cohere2(cohere2::load(weights, config).expect("model loads"))
        } else if name.starts_with("bailing_moe") {
            Self::Moe(bailing_moe::load(weights, config).expect("model loads"))
        } else if name.starts_with("falcon_h1") {
            Self::Falcon(falcon_h1::load(weights, config).expect("model loads"))
        } else {
            panic!("unknown flavor for case {name}");
        }
    }

    fn make_caches(&self) -> FixtureCaches {
        match self {
            FixtureModel::Dense(model) => {
                FixtureCaches::Dense(make_prompt_cache(model.config.num_hidden_layers))
            }
            FixtureModel::Moe(model) => {
                FixtureCaches::Dense(make_prompt_cache(model.config.num_hidden_layers))
            }
            FixtureModel::Gpt2(model) => {
                FixtureCaches::Dense(make_prompt_cache(model.config.n_layer))
            }
            FixtureModel::Cohere2(model) => FixtureCaches::Mixed(model.make_cache()),
            FixtureModel::Falcon(model) => FixtureCaches::Falcon(model.make_cache()),
        }
    }

    fn forward(
        &mut self,
        input: Input<'_>,
        caches: Option<&mut FixtureCaches>,
    ) -> Result<Vec<f32>> {
        match (self, caches) {
            (FixtureModel::Dense(model), None) => model.forward(input, None),
            (FixtureModel::Dense(model), Some(FixtureCaches::Dense(caches))) => {
                model.forward(input, Some(caches))
            }
            (FixtureModel::Gpt2(model), None) => model.forward(input, None),
            (FixtureModel::Gpt2(model), Some(FixtureCaches::Dense(caches))) => {
                model.forward(input, Some(caches))
            }
            (FixtureModel::Moe(model), None) => model.forward(input, None),
            (FixtureModel::Moe(model), Some(FixtureCaches::Dense(caches))) => {
                model.forward(input, Some(caches))
            }
            (FixtureModel::Cohere2(model), None) => model.forward(input, None),
            (FixtureModel::Cohere2(model), Some(FixtureCaches::Mixed(caches))) => {
                model.forward(input, Some(caches))
            }
            (FixtureModel::Falcon(model), None) => model.forward(input, None),
            (FixtureModel::Falcon(model), Some(FixtureCaches::Falcon(caches))) => {
                model.forward(input, Some(caches))
            }
            _ => panic!("cache flavor does not match the model"),
        }
    }

    fn forward_hidden(
        &mut self,
        input: Input<'_>,
        caches: Option<&mut FixtureCaches>,
    ) -> Result<Vec<f32>> {
        match (self, caches) {
            (FixtureModel::Dense(model), None) => model.forward_hidden(input, None),
            (FixtureModel::Dense(model), Some(FixtureCaches::Dense(caches))) => {
                model.forward_hidden(input, Some(caches))
            }
            (FixtureModel::Gpt2(model), None) => model.forward_hidden(input, None),
            (FixtureModel::Gpt2(model), Some(FixtureCaches::Dense(caches))) => {
                model.forward_hidden(input, Some(caches))
            }
            (FixtureModel::Moe(model), None) => model.forward_hidden(input, None),
            (FixtureModel::Moe(model), Some(FixtureCaches::Dense(caches))) => {
                model.forward_hidden(input, Some(caches))
            }
            (FixtureModel::Cohere2(model), None) => model.forward_hidden(input, None),
            (FixtureModel::Cohere2(model), Some(FixtureCaches::Mixed(caches))) => {
                model.forward_hidden(input, Some(caches))
            }
            (FixtureModel::Falcon(model), None) => model.forward_hidden(input, None),
            (FixtureModel::Falcon(model), Some(FixtureCaches::Falcon(caches))) => {
                model.forward_hidden(input, Some(caches))
            }
            _ => panic!("cache flavor does not match the model"),
        }
    }
}

/// The inputs a fixture carries: token ids for the standard cases, float
/// embeddings for the indextts-shaped gpt2 case.
enum FixtureInputs {
    Tokens { prefill: Vec<i32>, decode: Vec<i32> },
    Embeddings { prefill: Vec<f32>, decode: Vec<f32> },
}

impl FixtureInputs {
    fn from_traces(traces: &Value) -> Self {
        if let Some(rows) = traces.get("embeddings") {
            let decode_rows = traces["decode_embeddings"].as_array().unwrap();
            let row_width = rows.as_array().unwrap()[0].as_array().unwrap().len();
            let mut decode = Vec::new();
            for row in decode_rows {
                let values: Vec<f32> = row
                    .as_array()
                    .expect("decode embedding row")
                    .iter()
                    .map(|v| v.as_f64().unwrap() as f32)
                    .collect();
                assert_eq!(values.len(), row_width, "decode row width");
                decode.extend(values);
            }
            Self::Embeddings {
                prefill: f32_rows(rows),
                decode,
            }
        } else {
            Self::Tokens {
                prefill: traces["tokens"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|v| v.as_i64().unwrap() as i32)
                    .collect(),
                decode: traces["decode_tokens"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|v| v.as_i64().unwrap() as i32)
                    .collect(),
            }
        }
    }

    fn prefill(&self) -> Input<'_> {
        match self {
            FixtureInputs::Tokens { prefill, .. } => Input::Tokens(prefill),
            FixtureInputs::Embeddings { prefill, .. } => Input::Embeddings(prefill),
        }
    }

    fn decode_step(&self, step: usize, steps: usize) -> Input<'_> {
        match self {
            FixtureInputs::Tokens { decode, .. } => Input::Tokens(&decode[step..step + 1]),
            FixtureInputs::Embeddings { decode, .. } => {
                let width = decode.len() / steps;
                Input::Embeddings(&decode[step * width..(step + 1) * width])
            }
        }
    }
}

#[test]
fn max_abs_diff_propagates_nan_instead_of_passing_vacuously() {
    // f32::max drops NaN: a NaN model output once compared as a 0.0 diff
    // and the tolerance assert passed. The gate must stay NaN-toxic.
    let got = [f32::NAN, 1.0, 2.0];
    let want = [1.0, 1.0, 2.0];
    assert!(max_abs_diff(&got, &want).is_nan());
    let got = [0.0, f32::NAN];
    let want = [0.0, 1.0];
    assert!(max_abs_diff(&got, &want).is_nan());
    assert_eq!(max_abs_diff(&[1.0, -3.0], &[0.5, 3.0]), 6.0);
}

/// The falcon_h1 Mamba states a fixture pins: per layer, the conv buffer
/// and the selective-scan state (each optional until the first call).
fn falcon_state_diff(cache: &falcon_h1::FalconLayerCache, want: &Value) -> Option<f32> {
    let mut worst: Option<f32> = None;
    let mut consider = |got: &[f32], want: &Value| {
        let want: Vec<f32> = flatten_f32(want);
        let diff = max_abs_diff(got, &want);
        worst = Some(match worst {
            // Keep the NaN-propagation guarantee of max_abs_diff intact.
            Some(w) if (w.is_nan() || diff.is_nan()) => f32::NAN,
            Some(w) => w.max(diff),
            None => diff,
        });
    };
    let conv_want = want.get("conv").filter(|value| value.is_array());
    match (&cache.conv, conv_want) {
        (Some(conv), Some(want)) => consider(conv, want),
        (None, None) => {}
        (got, want) => panic!("conv state presence mismatch: {got:?} vs {want:?}"),
    }
    let ssm_want = want.get("ssm").filter(|value| value.is_array());
    match (&cache.ssm, ssm_want) {
        (Some(ssm), Some(want)) => consider(ssm, want),
        (None, None) => {}
        (got, want) => panic!("ssm state presence mismatch: {got:?} vs {want:?}"),
    }
    worst
}

/// Flattens nested JSON number arrays to f32.
fn flatten_f32(value: &Value) -> Vec<f32> {
    match value {
        Value::Number(number) => vec![number.as_f64().unwrap() as f32],
        Value::Array(items) => items.iter().flat_map(flatten_f32).collect(),
        other => panic!("not a number array: {other}"),
    }
}

fn run_case(name: &str) {
    let dir = testdata(name);
    let weights = Weights::open(&dir).expect("weights");
    let config = read_json(&dir.join("config.json"));
    let mut model = FixtureModel::load(name, &weights, &config);

    let traces = read_json(&dir.join("traces.json"));
    let inputs = FixtureInputs::from_traces(&traces);
    let decode_steps = traces["decode_logits"].as_array().unwrap().len();

    // Prefill through a prompt cache.
    let mut caches = model.make_caches();
    let logits = model
        .forward(inputs.prefill(), Some(&mut caches))
        .expect("prefill");
    let prefill = f32_rows(&traces["prefill_logits"]);
    let diff = max_abs_diff(&logits, &prefill);
    assert!(
        diff <= LOGITS_TOLERANCE,
        "{name} prefill logits diff {diff}"
    );

    // Falcon_h1 pins the Mamba conv/ssm state after every cached call.
    if let Some(states) = traces.get("mamba_states") {
        if let (FixtureCaches::Falcon(falcon_caches), Some(prefill_states)) =
            (&caches, states["prefill"].as_array())
        {
            for (cache, want) in falcon_caches.iter().zip(prefill_states) {
                if let Some(diff) = falcon_state_diff(cache, want) {
                    assert!(
                        diff <= STATE_TOLERANCE,
                        "{name} prefill ssm state diff {diff}"
                    );
                }
            }
        }
    }

    // Optional multi-token chunk (the cohere2 streaming case): a second
    // prefill after the window is full exercises the concat trim path and
    // the clamped-offset window mask.
    if let Some(chunk) = traces.get("chunk_tokens").filter(|value| !value.is_null()) {
        let tokens: Vec<i32> = chunk
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_i64().unwrap() as i32)
            .collect();
        let logits = model
            .forward(Input::Tokens(&tokens), Some(&mut caches))
            .unwrap_or_else(|error| panic!("{name} chunk: {error}"));
        let want = f32_rows(&traces["chunk_logits"]);
        let diff = max_abs_diff(&logits, &want);
        assert!(diff <= LOGITS_TOLERANCE, "{name} chunk diff {diff}");
    }

    // Cached decode steps: one input each, same caches.
    let decode_fixture: Vec<Vec<f32>> = traces["decode_logits"]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| {
            row.as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_f64().unwrap() as f32)
                .collect()
        })
        .collect();
    for (step, want) in decode_fixture.iter().enumerate() {
        let logits = model
            .forward(inputs.decode_step(step, decode_steps), Some(&mut caches))
            .unwrap_or_else(|error| panic!("{name} decode step {step}: {error}"));
        assert_eq!(logits.len(), want.len(), "{name} step {step} vocab width");
        let diff = max_abs_diff(&logits, want);
        assert!(
            diff <= LOGITS_TOLERANCE,
            "{name} decode step {step} diff {diff}"
        );
        if let Some(states) = traces.get("mamba_states") {
            if let (FixtureCaches::Falcon(falcon_caches), Some(step_states)) =
                (&caches, states["steps"][step].as_array())
            {
                println!(
                    "MEASURE step {step} comparing {} layer states",
                    falcon_caches.len()
                );
                let mut seen = 0.0f32;
                let _ = &mut seen;
                for (cache, state_want) in falcon_caches.iter().zip(step_states) {
                    if let Some(diff) = falcon_state_diff(cache, state_want) {
                        println!("MEASURE step {step} layer diff {diff}");
                        assert!(
                            diff <= STATE_TOLERANCE,
                            "{name} step {step} ssm state diff {diff}"
                        );
                    }
                }
            }
        }
    }

    // Cacheless pass.
    let cacheless = model.forward(inputs.prefill(), None).expect("cacheless");
    let want = f32_rows(&traces["cacheless_prefill_logits"]);
    let diff = max_abs_diff(&cacheless, &want);
    assert!(diff <= LOGITS_TOLERANCE, "{name} cacheless diff {diff}");

    // Hidden state before the head, through a fresh cache.
    let mut caches = model.make_caches();
    let hidden = model
        .forward_hidden(inputs.prefill(), Some(&mut caches))
        .expect("hidden");
    let want = f32_rows(&traces["hidden_state"]);
    let diff = max_abs_diff(&hidden, &want);
    assert!(diff <= HIDDEN_TOLERANCE, "{name} hidden state diff {diff}");
}

macro_rules! lm_case {
    ($name:ident) => {
        #[test]
        fn $name() {
            run_case(stringify!($name));
        }
    };
}

lm_case!(llama_default);
lm_case!(llama_llama3_rope);
lm_case!(llama_mrope_rope);
lm_case!(llama_linear_rope_untied);
lm_case!(llama_yarn_rope);
lm_case!(llama_longrope_rope);
lm_case!(llama_proportional_rope);
lm_case!(qwen2_default);
lm_case!(qwen3_default);
lm_case!(gpt2_default);
lm_case!(gpt2_indextts_embeddings);
lm_case!(cohere2_default);
lm_case!(cohere2_streaming);
lm_case!(bailing_moe_default);
lm_case!(falcon_h1_default);
lm_case!(falcon_h1_untied);

mod regressions {
    use serde_json::json;

    use super::super::engine::{Backbone, Input};
    use super::super::{cohere2, gpt2, llama, qwen3, PromptCache, Weights};
    use super::{read_json, testdata};

    fn weights() -> Weights {
        Weights::open(&testdata("llama_default")).unwrap()
    }

    fn llama_config() -> serde_json::Value {
        read_json(&testdata("llama_default").join("config.json"))
    }

    #[test]
    fn sliding_window_is_refused_until_the_rotating_cache_is_ported() {
        let config = llama::from_json(&json!({
            "model_type": "llama",
            "hidden_size": 8,
            "num_hidden_layers": 1,
            "intermediate_size": 8,
            "num_attention_heads": 2,
            "rms_norm_eps": 1e-5,
            "vocab_size": 8,
            "sliding_window": 16,
        }))
        .unwrap();
        let error = match Backbone::load(&weights(), config) {
            Err(error) => error,
            Ok(_) => panic!("sliding window must be refused"),
        };
        assert!(error.to_string().contains("sliding_attention"), "{error}");
    }

    #[test]
    fn non_full_layer_types_are_refused() {
        let error = llama::from_json(&json!({
            "model_type": "llama",
            "hidden_size": 8,
            "num_hidden_layers": 2,
            "intermediate_size": 8,
            "num_attention_heads": 2,
            "rms_norm_eps": 1e-5,
            "vocab_size": 8,
            "layer_types": ["full_attention", "sliding_attention"],
        }))
        .unwrap_err();
        assert!(error.to_string().contains("full_attention"), "{error}");
    }

    #[test]
    fn layer_type_length_must_match_layers() {
        let error = llama::from_json(&json!({
            "model_type": "llama",
            "hidden_size": 8,
            "num_hidden_layers": 2,
            "intermediate_size": 8,
            "num_attention_heads": 2,
            "rms_norm_eps": 1e-5,
            "vocab_size": 8,
            "layer_types": ["full_attention"],
        }))
        .unwrap_err();
        assert!(
            error.to_string().contains("1 entries for 2 layers"),
            "{error}"
        );
    }

    #[test]
    fn unsupported_rope_type_is_named() {
        // The rope construction runs at load time with the real shapes, so
        // this rides the fixture checkpoint's geometry.
        let mut config = llama_config();
        config["rope_scaling"] = json!({"type": "nope"});
        let error = match llama::load(&weights(), &config) {
            Err(error) => error,
            Ok(_) => panic!("an unknown rope type must be refused"),
        };
        assert!(error.to_string().contains("rope type nope"), "{error}");
    }

    #[test]
    fn qwen3_requires_every_reference_field() {
        let value = json!({
            "model_type": "qwen3",
            "hidden_size": 32,
            "num_hidden_layers": 2,
            "intermediate_size": 64,
            "num_attention_heads": 4,
            "rms_norm_eps": 1e-5,
            "vocab_size": 96,
            "num_key_value_heads": 2,
            "max_position_embeddings": 64,
            "rope_theta": 1000000.0,
            "tie_word_embeddings": true,
        });
        let error = qwen3::from_json(&value).unwrap_err();
        assert!(error.to_string().contains("head_dim"), "{error}");
    }

    #[test]
    fn out_of_vocab_and_negative_tokens_are_input_errors() {
        let weights = weights();
        let config = llama_config();
        let mut model = llama::load(&weights, &config).unwrap();
        let error = match model.forward(Input::Tokens(&[999_999]), None) {
            Err(error) => error,
            Ok(_) => panic!("out-of-vocab token must fail"),
        };
        assert!(error.to_string().contains("outside vocab"), "{error}");
        let error = match model.forward(Input::Tokens(&[-1]), None) {
            Err(error) => error,
            Ok(_) => panic!("negative token must fail"),
        };
        assert!(error.to_string().contains("negative token"), "{error}");
        let error = match model.forward(Input::Tokens(&[]), None) {
            Err(error) => error,
            Ok(_) => panic!("empty input must fail"),
        };
        assert!(error.to_string().contains("empty forward input"), "{error}");
    }

    #[test]
    fn cache_count_is_validated() {
        let weights = weights();
        let config = llama_config();
        let mut model = llama::load(&weights, &config).unwrap();
        let error = match model.forward(Input::Tokens(&[1]), Some(&mut Vec::new())) {
            Err(error) => error,
            Ok(_) => panic!("cache count mismatch must fail"),
        };
        assert!(error.to_string().contains("layer caches"), "{error}");
    }

    #[test]
    fn missing_weight_tensors_name_the_tensor() {
        let weights = weights();
        let mut config = llama_config();
        config["num_hidden_layers"] = json!(3);
        config["layer_types"] = json!(["full_attention", "full_attention", "full_attention"]);
        let error = match llama::load(&weights, &config) {
            Err(error) => error,
            Ok(_) => panic!("a missing layer must fail the load"),
        };
        assert!(
            error.to_string().contains("layers.2.self_attn.q_proj"),
            "{error}"
        );
    }

    #[test]
    fn qwen2_config_does_not_load_through_the_qwen3_parser() {
        // The qwen2 fixture config has no head_dim field; the qwen3
        // dataclass requires it, so the flavors cannot be crossed silently.
        let weights = Weights::open(&testdata("qwen2_default")).unwrap();
        let config = read_json(&testdata("qwen2_default").join("config.json"));
        let error = match qwen3::load(&weights, &config) {
            Err(error) => error,
            Ok(_) => panic!("a qwen2 config must not parse as qwen3"),
        };
        assert!(error.to_string().contains("head_dim"), "{error}");
    }

    #[test]
    fn cohere2_cache_pattern_splits_sliding_and_global_layers() {
        // Pattern 4 over 4 layers: 0..2 sliding rings, layer 3 global.
        let weights = Weights::open(&testdata("cohere2_default")).unwrap();
        let config = read_json(&testdata("cohere2_default").join("config.json"));
        let model = cohere2::load(&weights, &config).unwrap();
        let caches = model.make_cache();
        assert_eq!(caches.len(), 4);
        for (index, cache) in caches.iter().enumerate() {
            let global = index % 4 == 3;
            assert_eq!(
                matches!(cache, PromptCache::Dense(_)),
                global,
                "layer {index}"
            );
        }
    }

    #[test]
    fn gpt2_positions_beyond_the_table_are_refused() {
        let weights = Weights::open(&testdata("gpt2_default")).unwrap();
        let config = read_json(&testdata("gpt2_default").join("config.json"));
        let mut model = gpt2::load(&weights, &config).unwrap();
        // 65 tokens of a 64-position table: the last position lookup must
        // refuse instead of wrapping or panicking.
        let tokens: Vec<i32> = (0..65).collect();
        let error = match model.forward(Input::Tokens(&tokens), None) {
            Err(error) => error,
            Ok(_) => panic!("position past n_positions must fail"),
        };
        assert!(error.to_string().contains("outside n_positions"), "{error}");
    }

    #[test]
    fn gpt2_indextts_style_loading_drops_the_position_table() {
        let weights = Weights::open(&testdata("gpt2_indextts_embeddings")).unwrap();
        let config = read_json(&testdata("gpt2_indextts_embeddings").join("config.json"));
        let model = gpt2::load(&weights, &config)
            .unwrap()
            .without_position_embeddings();
        // The indextts fixture drives the model with n_positions wide past
        // the dropped table; make sure the builder actually dropped it by
        // driving 7 positions (the case would fail at load if the table
        // were required to cover them).
        let traces = read_json(&testdata("gpt2_indextts_embeddings").join("traces.json"));
        let prefill: Vec<f32> = traces["embeddings"]
            .as_array()
            .unwrap()
            .iter()
            .flat_map(|row| {
                row.as_array()
                    .unwrap()
                    .iter()
                    .map(|v| v.as_f64().unwrap() as f32)
            })
            .collect();
        let mut model = model;
        model
            .forward_hidden(Input::Embeddings(&prefill), None)
            .expect("embeddings forward without the position table");
    }

    #[test]
    fn dense_config_defaults_mirror_the_reference_dataclass() {
        let config = llama::from_json(&json!({
            "model_type": "llama",
            "hidden_size": 16,
            "num_hidden_layers": 1,
            "intermediate_size": 16,
            "num_attention_heads": 4,
            "rms_norm_eps": 1e-5,
            "vocab_size": 8,
        }))
        .unwrap();
        assert_eq!(config.num_key_value_heads, 4);
        assert!(!config.attention_bias);
        assert!(!config.mlp_bias);
        assert_eq!(config.rope_theta, 10000.0);
        assert!(config.tie_word_embeddings);
        assert_eq!(config.head_dim, 4);
        assert_eq!(config.sliding_window, None);
    }
}

